const [items, setItems] = useState([{id: "1", title: "First"}, {id: "2", title: "Second"}]);

<SortableList
  items={items}
  onChange={setItems}
  renderItem={(item) => (
    <SortableCardWrapper id={item.id}>
      <Card><CardHeader>{item.title}</CardHeader></Card>
    </SortableCardWrapper>
  )}
/>

function SortableCardWrapper({id, children}) {
  const { setNodeRef, attributes, listeners, style } = useSortableItem(id);
  return <div ref={setNodeRef} style={style} {...attributes} {...listeners}>{children}</div>;
}

// Inside a <DndProvider> wrapping the table body:
function SortableRow({id, children}) {
  const { setNodeRef, attributes, listeners, style, isDragging } = useSortableItem(id);
  return (
    <TableRow ref={setNodeRef} style={style} {...attributes} className={isDragging ? "opacity-50" : ""}>
      <TableCell><span {...listeners} className="cursor-grab">⠿</span></TableCell>
      {children}
    </TableRow>
  );
}
